WITH p AS (SELECT %s::date d1,%s::date d2,coalesce(%s::text,'') search_key,%s::integer uid,%s::integer lim), s AS (SELECT p.*,u.user_id ok,coalesce(u.ds_branchs,'') bs,coalesce(u.is_super,0)=1 OR coalesce(u.ds_branchs,'')='' all_branch FROM p LEFT JOIN public.userinfo u ON u.user_id=p.uid) SELECT a.ma_dvcs,a.stt_rec,a.ma_ct,a.ma_gd,a.ngay_ct,a.ngay_lct,a.so_ct,a.branch_code,a.factory_code,a.work_center_code,a.start_date,a.end_date,a.date0,a.time0,a.status,a.use_lsx,a.use_machine,a.loss_time,a.mold_change,a.plastics_change,count(*) OVER() total FROM public.mes_scheduling a CROSS JOIN s WHERE s.ok IS NOT NULL AND a.ngay_ct BETWEEN s.d1 AND s.d2 AND (s.search_key='' OR a.so_ct ILIKE '%%'||s.search_key||'%%' OR a.work_center_code=ANY(string_to_array(s.search_key,','))) AND (s.all_branch OR a.ma_dvcs=ANY(string_to_array(s.bs,',')) OR a.branch_code=ANY(string_to_array(s.bs,','))) ORDER BY a.ngay_ct DESC,a.so_ct LIMIT (SELECT lim FROM p);
